// Min-Heap using PriorityQueue
PriorityQueue<Integer> minHeap = new PriorityQueue<>();

// Max-Heap using PriorityQueue with a custom comparator
PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder());

minHeap.add(10);
minHeap.add(20);
minHeap.add(5);
System.out.println(minHeap.peek());  // Output: 5 (min element in min-heap)

maxHeap.add(10);
maxHeap.add(20);
maxHeap.add(5);
System.out.println(maxHeap.peek());  // Output: 20 (max element in max-heap)

PriorityQueue<Integer> heap = new PriorityQueue<>();
heap.add(10);
heap.add(15);
heap.add(5);

System.out.println(heap.poll());  // Output: 5 (min element removed)
System.out.println(heap.poll());  // Output: 10

public void heapSort(int[] arr) {
    int n = arr.length;

    // Build max heap
    for (int i = n / 2 - 1; i >= 0; i--) {
        heapify(arr, n, i);
    }

    // Extract elements from heap one by one
    for (int i = n - 1; i > 0; i--) {
        // Move current root to end
        int temp = arr[0];
        arr[0] = arr[i];
        arr[i] = temp;

        // Heapify the reduced heap
        heapify(arr, i, 0);
    }
}

void heapify(int[] arr, int n, int i) {
    int largest = i;
    int left = 2 * i + 1;
    int right = 2 * i + 2;

    if (left < n && arr[left] > arr[largest]) {
        largest = left;
    }

    if (right < n && arr[right] > arr[largest]) {
        largest = right;
    }

    if (largest != i) {
        int swap = arr[i];
        arr[i] = arr[largest];
        arr[largest] = swap;

        heapify(arr, n, largest);
    }
}

